#!/usr/bin/env node
/**
 * fluid-root.mjs — the house fluid root font-size snippet, generated and audited.
 *
 * Every site we build scales its whole type and spacing system from one fluid
 * root font-size, so a `rem` is viewport-relative and nothing needs a per-element
 * media query. This is the Finsweet Fluid Design Generator technique, pinned here
 * so the output is identical on every client instead of re-generated by hand.
 *
 * Usage:
 *   node scripts/fluid-root.mjs                 print the <style> block (paste into <head>)
 *   node scripts/fluid-root.mjs --css           print bare CSS (paste into a shared .css)
 *   node scripts/fluid-root.mjs --verify        print rendered root px at sample widths
 *   node scripts/fluid-root.mjs --check <path>  audit built pages/CSS for compliance
 *   node scripts/fluid-root.mjs --config f.json use a custom breakpoint table
 *
 * Docs: deliver/process/04-design/fluid-root.md
 */

import fs from 'node:fs'
import path from 'node:path'

/**
 * The house scale. Each segment is [screenWidthPx, rootFontPx] at its two ends.
 * Segments are listed small -> large and must be contiguous on width.
 * A deliberate step between segments is allowed (see 479 below).
 */
const HOUSE_SCALE = {
  name: 'webzite-house-v1',
  segments: [
    { from: { w: 320, px: 12 }, to: { w: 479, px: 16 } },
    { from: { w: 479, px: 14 }, to: { w: 1440, px: 16 } },
    { from: { w: 1440, px: 16 }, to: { w: 1920, px: 18 } },
    { from: { w: 1920, px: 18 }, to: { w: 2400, px: 20 } },
  ],
}

const FORMULA = [
  '  --coefficient: calc((var(--font-to) - var(--font-from)) / (var(--vw-to) - var(--vw-from)));',
  '  --base: calc((var(--font-from) - var(--vw-from) * var(--coefficient)) / 16);',
].join('\n')

function vars (seg, indent) {
  const p = ' '.repeat(indent)
  return [
    `${p}--font-from: ${seg.from.px};`,
    `${p}--font-to: ${seg.to.px};`,
    `${p}--vw-from: calc(${seg.from.w} / 100);`,
    `${p}--vw-to: calc(${seg.to.w} / 100);`,
  ].join('\n')
}

/**
 * Emit the cascade. The largest segment is the base rule; each smaller segment
 * is a max-width query that only overrides the four inputs — --coefficient and
 * --base are custom properties resolved at computed-value time, so they pick up
 * the new inputs automatically and never need repeating.
 */
export function generate (scale = HOUSE_SCALE) {
  const segs = [...scale.segments].sort((a, b) => a.from.w - b.from.w)
  const top = segs[segs.length - 1]
  const out = [
    `/* Fluid root font-size — ${scale.name}. Generated by scripts/fluid-root.mjs; do not hand-edit. */`,
    ':root {',
    vars(top, 2),
    FORMULA,
    '}',
    '',
    'html {',
    '  font-size: calc(var(--base) * 1rem + var(--coefficient) * 1vw);',
    '}',
  ]
  // Descend: each query caps at the *upper* bound of the segment it activates.
  for (let i = segs.length - 2; i >= 0; i--) {
    out.push('', `@media screen and (max-width: ${segs[i].to.w}px) {`, '  :root {', vars(segs[i], 4), '  }', '}')
  }
  return out.join('\n') + '\n'
}

/** Rendered root font-size in px at a given viewport width, per the emitted cascade. */
export function rootPxAt (width, scale = HOUSE_SCALE) {
  const segs = [...scale.segments].sort((a, b) => a.from.w - b.from.w)
  // max-width queries cascade downward: the narrowest matching query wins.
  let active = segs[segs.length - 1]
  for (let i = segs.length - 2; i >= 0; i--) if (width <= segs[i].to.w) active = segs[i]
  const vwFrom = active.from.w / 100
  const vwTo = active.to.w / 100
  const coefficient = (active.to.px - active.from.px) / (vwTo - vwFrom)
  const base = (active.from.px - vwFrom * coefficient) / 16
  return base * 16 + coefficient * (width / 100)
}

const WALK_EXT = new Set(['.html', '.css'])
function walk (target, acc = []) {
  const st = fs.statSync(target)
  if (st.isFile()) { if (WALK_EXT.has(path.extname(target))) acc.push(target); return acc }
  for (const e of fs.readdirSync(target, { withFileTypes: true })) {
    if (e.name === 'node_modules' || e.name === '.git' || e.name === 'vendor') continue
    walk(path.join(target, e.name), acc)
  }
  return acc
}

/**
 * Audit. A page is compliant when the fluid root is installed, type is sized in
 * rem, and nothing re-introduces a fixed or double-scaling root.
 */
function check (targets) {
  const files = targets.flatMap((t) => walk(path.resolve(t)))
  // `_`-prefixed HTML is an internal partial or contact sheet, not a shipped page.
  const htmls = files.filter((f) => f.endsWith('.html') && !path.basename(f).startsWith('_'))
  const problems = []
  let installed = 0

  // The snippet may live in a linked stylesheet, so resolve local <link>/<script> siblings.
  const readWithLinked = (file) => {
    const src = fs.readFileSync(file, 'utf8')
    let combined = src
    for (const m of src.matchAll(/<link[^>]+href=["']([^"']+\.css)["']/gi)) {
      const p = path.resolve(path.dirname(file), m[1].split('?')[0])
      if (fs.existsSync(p)) combined += '\n' + fs.readFileSync(p, 'utf8')
    }
    return { src, combined }
  }

  for (const file of htmls) {
    const { combined } = readWithLinked(file)
    const rel = path.relative(process.cwd(), file)
    const has = /--coefficient\s*:/.test(combined) && /font-size:\s*calc\(var\(--base\)/.test(combined)
    if (has) installed++
    else problems.push({ rel, kind: 'missing', detail: 'fluid root snippet not found (page or linked CSS)' })

    // A later `html{font-size:...}` or `:root{font-size:...}` overrides the fluid root.
    for (const m of combined.matchAll(/(?:^|[},])\s*(?:html|:root)\s*{[^}]*?font-size:\s*([^;}]+)/gi)) {
      if (!/calc\(var\(--base\)/.test(m[1])) {
        problems.push({ rel, kind: 'override', detail: `root font-size overridden: ${m[1].trim()}` })
      }
    }
    // px type defeats the whole mechanism; clamp()+vw double-scales against a fluid root.
    for (const m of combined.matchAll(/font-size:\s*([0-9.]+px)/gi)) {
      problems.push({ rel, kind: 'px', detail: `px font-size: ${m[1]}` })
    }
    for (const m of combined.matchAll(/font-size:\s*(clamp\([^)]*\))/gi)) {
      problems.push({ rel, kind: 'clamp', detail: `clamp() font-size double-scales: ${m[1]}` })
    }
    // rem-based media queries move with the root and produce breakpoint feedback loops.
    for (const m of combined.matchAll(/@media[^{]*\(\s*(?:min|max)-width:\s*([0-9.]+r?em)\s*\)/gi)) {
      if (/rem$/.test(m[1])) problems.push({ rel, kind: 'mq-rem', detail: `media query in rem: ${m[1]}` })
    }
  }

  const byKind = problems.reduce((a, p) => ((a[p.kind] = (a[p.kind] || 0) + 1), a), {})
  const seen = new Set()
  for (const p of problems) {
    const key = `${p.rel}|${p.detail}`
    if (seen.has(key)) continue
    seen.add(key)
    console.log(`  ${p.kind.padEnd(9)} ${p.rel}: ${p.detail}`)
  }
  console.log(`\n${installed}/${htmls.length} pages carry the fluid root.`)
  console.log(`Problems: ${Object.entries(byKind).map(([k, v]) => `${k}=${v}`).join(' ') || 'none'}`)
  return problems.length === 0 && installed === htmls.length
}

const argv = process.argv.slice(2)
const cfgIdx = argv.indexOf('--config')
const scale = cfgIdx !== -1 ? JSON.parse(fs.readFileSync(argv[cfgIdx + 1], 'utf8')) : HOUSE_SCALE

if (argv.includes('--check')) {
  const targets = argv.slice(argv.indexOf('--check') + 1).filter((a) => !a.startsWith('--'))
  process.exit(check(targets.length ? targets : ['.']) ? 0 : 1)
} else if (argv.includes('--verify')) {
  console.log(`${scale.name} — rendered root font-size\n`)
  for (const w of [320, 390, 479, 480, 768, 991, 1280, 1440, 1920, 2400, 2560]) {
    console.log(`  ${String(w).padStart(4)}px viewport -> ${rootPxAt(w, scale).toFixed(2)}px root`)
  }
} else if (argv.includes('--css')) {
  process.stdout.write(generate(scale))
} else {
  process.stdout.write('<style>\n' + generate(scale) + '</style>\n')
}
